effect.shader:
void main() {
  vec2 uv = acScreenNorm * 2.0 - 1.0; // Convert to range [-1, 1]
  float r = length(uv); // Distance from center

  // Lens distortion formula
  float k = strength; // distortion strength
  float distortedR = r + k * r * r;
  vec2 distortedUV = uv * (distortedR / max(r, 0.0001));
  distortedUV = (distortedUV + 1.0) * 0.5; // Back to [0, 1]

  // Only use distorted coordinates if inside bounds
  vec4 color = vec4(0.0);
  if (distortedUV.x >= 0.0 && distortedUV.x <= 1.0 && distortedUV.y >= 0.0 && distortedUV.y <= 1.0) {
    color = texture2DCv(inputImg.texture, distortedUV);
  }

  // Blend with the original image
  vec4 orig = texture2DCv(inputImg.texture, acScreenNorm);
  vec4 finalColor = mix(orig, color, blend);

  gl_FragColor = finalColor;
}
